var d = msg.payload;
if (!d || typeof d !== 'object') { node.warn('No sensor data'); return null; }

function safeInt(v)   { var n = parseInt(v);   return isNaN(n) ? null : n; }
function safeFloat(v) { var n = parseFloat(v); return isNaN(n) ? null : n; }

var temp = safeFloat(d.temperature) !== null ? safeFloat(d.temperature) : 0;
var humi = safeFloat(d.humidity)    !== null ? safeFloat(d.humidity)    : 0;

var soilPct = (function() {
  var candidates = [d.soil_pct, d.soil_moisture, d.soil, d.soilMoisture];
  for (var i = 0; i < candidates.length; i++) {
    var v = safeInt(candidates[i]);
    if (v !== null) return v;
  }
  return 0;
})();

var lightPct = (function() {
  var candidates = [d.light_pct, d.light_level, d.light];
  for (var i = 0; i < candidates.length; i++) {
    var v = safeInt(candidates[i]);
    if (v !== null) return v;
  }
  return 0;
})();

var soilLabel  = soilPct < 30 ? 'DRY' : soilPct > 80 ? 'WET SATURATED' : 'GOOD';
var soilColour = soilPct < 30 ? '#e63946' : soilPct > 80 ? '#2196F3' : '#4CAF50';

var hour = new Date().getHours();
var isDaytime = hour >= 7 && hour < 18;
var lightWarn = isDaytime && lightPct < 20;
var lightLabel = lightWarn ? 'LOW' : (lightPct < 20 ? 'DARK' : 'BRIGHT');
var lightColour = lightWarn ? '#FF9800' : (lightPct < 20 ? '#607D8B' : '#FFC107');

var tempColour = temp > 30 ? '#e63946' : temp < 18 ? '#2196F3' : '#4CAF50';
var tempLabel  = temp > 30 ? 'HIGH' : temp < 18 ? 'COLD' : 'NORMAL';

return [
  { payload: temp },
  { payload: humi },
  { payload: soilPct },
  { payload: lightPct },
  { payload: '<div style="text-align:center;margin-top:6px"><span style="background:' + soilColour + ';color:#fff;padding:4px 14px;border-radius:20px;font-weight:bold">' + soilLabel + ' (' + soilPct + '%)</span></div>' },
  { payload: '<div style="text-align:center;margin-top:6px"><span style="background:' + lightColour + ';color:#fff;padding:4px 14px;border-radius:20px;font-weight:bold">' + lightLabel + ' (' + lightPct + '%)</span></div>' },
  { payload: '<div style="text-align:center;margin-top:6px"><span style="background:' + tempColour + ';color:#fff;padding:4px 14px;border-radius:20px;font-weight:bold">' + tempLabel + ' (' + temp + 'C)</span></div>' },
  { payload: new Date().toLocaleString('en-MY') },
  { payload: temp,    topic: 'Temperature (C)' },
  { payload: humi,    topic: 'Humidity (%)' },
  { payload: soilPct, topic: 'Soil Moisture (%)' }
];

var d=msg.payload;
if(!d||typeof d!=='object')return null;
var fanOn=d.fan&&d.fan.state;
var pumpOn=d.pump&&d.pump.state;
var lightOn=d.growLight&&d.growLight.state;
function badge(on,a,b){var c=on?'#4CAF50':'#9E9E9E';return '<span style="background:'+c+';color:#fff;padding:3px 12px;border-radius:20px;font-weight:bold">'+(on?a:b)+'</span>';}
return [{payload:badge(fanOn,'FAN ON','FAN OFF')},{payload:badge(pumpOn,'PUMP ON','PUMP OFF')},{payload:badge(lightOn,'LIGHT ON','LIGHT OFF')}];

var d=msg.payload;
if(!d||typeof d!=='object'){return{payload:'<p>No alerts.</p>'};}
var rows=Object.values(d).reverse().map(function(a){var c=a.level==='critical'?'#e63946':'#FF9800';return '<div style="border-left:4px solid '+c+';padding:6px 10px;margin:4px 0"><strong>'+a.message+'</strong></div>';}).join('');
return{payload:rows};

var device=msg.topic;
var state=msg.payload==='ON';
msg.url='https://iot-greenhouse-assignment-default-rtdb.asia-southeast1.firebasedatabase.app/actuators/status/'+device+'.json?auth=s85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV';
msg.method='PATCH';
msg.headers={'Content-Type':'application/json'};
msg.payload=JSON.stringify({state:state,manual:true,updated:new Date().toISOString()});
return msg;

var key = msg.topic;  // e.g. 'temp_max', 'soil_min'
var val = parseFloat(msg.payload);

// Out 1: Firebase PATCH
var firebaseMsg = {
  url:     'https://iot-greenhouse-assignment-default-rtdb.asia-southeast1.firebasedatabase.app/thresholds.json?auth=s85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV',
  method:  'PATCH',
  headers: { 'Content-Type': 'application/json' },
  payload: JSON.stringify({ [key]: val })
};

// Out 2: MQTT publish so ESP32 receives the updated threshold live
var mqttMsg = {
  payload: JSON.stringify({ [key]: val }),
  topic:   'bmit2123_assg/greenhouse/thresholds'
};

node.status({ fill:'green', shape:'dot', text: key + ' -> ' + val });
return [firebaseMsg, mqttMsg];

var d=msg.payload;
if(!d||typeof d!=='object')return null;
var entries=Object.values(d);
if(entries.length===0)return null;
var latest=entries[entries.length-1];
var lastKey=Object.keys(d).pop();
var seen=context.get('lastAlertKey')||'';
if(lastKey===seen)return null;
context.set('lastAlertKey',lastKey);
return{payload:(latest.level==='critical'?'CRITICAL':'WARNING')+': '+latest.message};

flow.set('lastSensorTime', Date.now());
flow.set('sensorOffline', false);

var d = msg.payload;
if (!d || typeof d !== 'object') {
  node.warn('Invalid sensor payload: ' + JSON.stringify(d));
  return null;
}

function safeInt(v)   { var n = parseInt(v);   return isNaN(n) ? null : n; }
function safeFloat(v) { var n = parseFloat(v); return isNaN(n) ? null : n; }

var temp = safeFloat(d.temperature) !== null ? safeFloat(d.temperature) : 0;
var humi = safeFloat(d.humidity)    !== null ? safeFloat(d.humidity)    : 0;

var soilPct = (function() {
  var candidates = [d.soil_pct, d.soil_moisture, d.soil, d.soilMoisture];
  for (var i = 0; i < candidates.length; i++) {
    var v = safeInt(candidates[i]);
    if (v !== null) return v;
  }
  return 0;
})();

var lightPct = (function() {
  var candidates = [d.light_pct, d.light_level, d.lightLevel, d.light];
  for (var i = 0; i < candidates.length; i++) {
    var v = safeInt(candidates[i]);
    if (v !== null) return v;
  }
  return 0;
})();

node.warn('COMPUTED: soilPct=' + soilPct + ' lightPct=' + lightPct);

var now = new Date().toISOString();

var sensorMsg = { payload: {
  temperature: parseFloat(temp.toFixed(1)),
  humidity:    parseFloat(humi.toFixed(1)),
  soil_pct:    soilPct,
  light_pct:   lightPct,
  timestamp:   now
}};

function toState(v) {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'string')  return v.toUpperCase() === 'ON';
  return !!v;
}
var actuatorMsg = { payload: {
  fan:       { state: toState(d.fan),   updated: now, manual: false },
  pump:      { state: toState(d.pump),  updated: now, manual: false },
  growLight: { state: toState(d.light), updated: now, manual: false }
}};

node.status({ fill:'green', shape:'dot',
  text: 'T:' + temp.toFixed(1) + 'C S:' + soilPct + '% L:' + lightPct + '%' });
return [sensorMsg, actuatorMsg];

var d   = msg.payload;
var thr = flow.get('thresholds') || {
  temp_max: 30, temp_min: 28,
  soil_min: 30, soil_max: 60,
  light_day_min: 20, humidity_max: 85
};

var alerts = [];

if (d.temperature > thr.temp_max + 5)
  alerts.push({ level:'critical', message:'Temperature critically high: ' + d.temperature + 'C' });
else if (d.temperature > thr.temp_max)
  alerts.push({ level:'warning',  message:'Temperature high: ' + d.temperature + 'C' });

if (d.humidity > (thr.humidity_max || 85))
  alerts.push({ level:'warning', message:'Humidity very high: ' + d.humidity + '%' });

if (d.soil_pct < thr.soil_min - 10)
  alerts.push({ level:'critical', message:'Soil critically dry: ' + d.soil_pct + '%' });
else if (d.soil_pct < thr.soil_min)
  alerts.push({ level:'warning',  message:'Soil moisture low: ' + d.soil_pct + '%' });

if (alerts.length === 0) return null;

var ts = Date.now();
alerts.forEach(function(a, i) {
  a.timestamp = new Date(ts + i).toLocaleString('en-MY', { timeZone: 'Asia/Kuala_Lumpur' });
});
msg.alerts = alerts;
return msg;

var d=msg.payload;
if(!d||typeof d!=='object'){return null;}
function toState(v){if(typeof v==='boolean')return v;if(typeof v==='string')return v.toUpperCase()==='ON';return!!v;}
var now=new Date().toISOString();
msg.payload={fan:{state:toState(d.fan),updated:now,manual:false},pump:{state:toState(d.pump),updated:now,manual:false},growLight:{state:toState(d.growLight||d.light),updated:now,manual:false}};
return msg;

var d=msg.payload;
if(!d||typeof d!=='object')return null;
var existing=flow.get('thresholds')||{};
var merged=Object.assign({},existing,d);
flow.set('thresholds',merged);
var secret='s85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV';
msg.url='https://iot-greenhouse-assignment-default-rtdb.asia-southeast1.firebasedatabase.app/thresholds.json?auth='+secret;
msg.method='PATCH';
msg.headers={'Content-Type':'application/json'};
msg.payload=JSON.stringify(d);
return msg;

var device = msg.topic;  // 'fan' | 'pump' | 'growLight'

// msg.payload is JSON string from Manual Override function
var state = false;
if (typeof msg.payload === 'string') {
  try { state = JSON.parse(msg.payload).state === true; } catch(e) {}
} else if (msg.payload && typeof msg.payload === 'object') {
  state = msg.payload.state === true;
}

// ESP32 uses key 'light' not 'growLight'
var espKey = (device === 'growLight') ? 'light' : device;

// ESP32 callback checks: doc['fan'] == 'ON'  → MUST be string, not boolean
msg.payload = JSON.stringify({ [espKey]: state ? 'ON' : 'OFF' });
msg.topic   = 'bmit2123_assg/greenhouse/actuators';
node.status({ fill:'orange', shape:'dot',
  text: 'CMD ' + espKey + ' -> ' + (state ? 'ON' : 'OFF') });
return msg;

var d = msg.payload;
var defaults = {
  temp_max: 30, temp_min: 28,
  soil_min: 30, soil_max: 60,
  light_day_min: 20, humidity_max: 85, temp_cold: 15
};
var merged = Object.assign({}, defaults, (d && typeof d === 'object') ? d : {});
flow.set('thresholds', merged);
node.status({ fill:'green', shape:'dot', text:'thresholds cached' });
return null;

var secret = 's85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV';
msg.url     = 'https://iot-greenhouse-assignment-default-rtdb.asia-southeast1.firebasedatabase.app/actuators/status.json?auth=' + secret;
msg.method  = 'PUT';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = JSON.stringify(msg.payload);
return msg;
